import React, { useState } from 'react';

export default function AddAdvertisement() {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [link, setLink] = useState('');
  const [message, setMessage] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!title || !content) {
      setMessage('Title and Content are required.');
      return;
    }

    try {
      const response = await fetch('http://localhost:5000/advertisements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, content, link }),
      });
      if (response.ok) {
        setMessage('Advertisement added successfully.');
        setTitle('');
        setContent('');
        setLink('');
      } else {
        setMessage('Failed to add advertisement.');
      }
    } catch (error) {
      setMessage('Error: ' + error.message);
    }
  };

  return (
    <div style={{ maxWidth: '400px', margin: 'auto', padding: '20px' }}>
      <h2>Add Advertisement</h2>
      {message && <p>{message}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label>Title</label><br />
          <input 
            type="text" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            required 
          />
        </div>
        <div>
          <label>Content</label><br />
          <textarea 
            value={content} 
            onChange={e => setContent(e.target.value)} 
            required 
            rows="4"
          />
        </div>
        <div>
          <label>Link (Optional)</label><br />
          <input 
            type="text" 
            value={link} 
            onChange={e => setLink(e.target.value)} 
            placeholder="https://example.com"
          />
        </div>
        <button type="submit" style={{ marginTop: '10px' }}>Add Advertisement</button>
      </form>
    </div>
  );
}
